// js-ts-conventions — custom lint rules for preferences no stock rule covers.
//
// Generated by the js-ts-conventions skill. Do not edit this copy: change the
// skill's catalog and re-run enforce. Per-repo tweaks go in
// .js-ts-conventions/overrides.json.
//
// One ESLint-compatible plugin, loaded by ESLint (flat config `plugins`) and
// by oxlint (`jsPlugins`), so both linters report the same rule ids.
// Zero dependencies on purpose: it must load from any repo.

const CAMEL = /^[a-z][a-zA-Z0-9]*$/;
const PASCAL = /^[A-Z][a-zA-Z0-9]*$/;
const UPPER = /^[A-Z][A-Z0-9]*(?:_[A-Z0-9]+)*$/;
const KEBAB_SEGMENT =
  /^(?:[_$+]?[a-z0-9]+(?:-[a-z0-9]+)*|\[{1,2}(?:\.\.\.)?[A-Za-z0-9_-]+\]{1,2})$/;
const SOURCE_EXTENSION = /^(.*?)((?:\.d)?\.[cm]?[jt]sx?)$/;

// Framework-mandated module exports that must keep their exact name.
const FRAMEWORK_CONSTANTS = new Set([
  "dynamic", "dynamicParams", "revalidate", "fetchCache", "runtime",
  "preferredRegion", "maxDuration", "experimental_ppr",
  "prerender", "ssr", "csr", "trailingSlash",
]);

/** Leading `_`/`$` and trailing `_` carry no casing information. */
function bare(name) {
  return name.replace(/^[_$]+/, "").replace(/_+$/, "");
}

function keyName(key) {
  if (!key) return undefined;
  if (key.type === "Identifier") return key.name;
  if (key.type === "PrivateIdentifier") return `#${key.name}`;
  if (key.type === "Literal" && typeof key.value === "string") return key.value;
  return undefined;
}

function isJsxFile(filename) {
  return /\.[jt]sx$/.test(filename);
}

const DECORATOR_FACTORIES = new Set(["applyDecorators", "SetMetadata", "createParamDecorator"]);

// Route handlers (Next.js `route.ts`, SvelteKit `+server.ts`, Astro endpoints) must use these names.
const HTTP_METHOD_HANDLERS = new Set(["GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS", "ALL"]);

/** Decorator factories (`function Roles(): MethodDecorator`) are PascalCase by convention. */
function isDecoratorFactory(fn) {
  const returnType = fn.returnType?.typeAnnotation;
  if (returnType?.type === "TSTypeReference" && (returnType.typeName?.name ?? "").endsWith("Decorator")) {
    return true;
  }
  return (fn.body?.body ?? []).some(
    (statement) =>
      statement.type === "ReturnStatement" &&
      statement.argument?.type === "CallExpression" &&
      DECORATOR_FACTORIES.has(statement.argument.callee?.name),
  );
}

function basename(filename) {
  return filename.split(/[\\/]/).pop() ?? filename;
}

function toUpperSnake(name) {
  return bare(name)
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/[-\s]+/g, "_")
    .toUpperCase();
}

function toKebab(name) {
  return name
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/([A-Z])([A-Z][a-z])/g, "$1-$2")
    .replace(/[_\s]+/g, "-")
    .toLowerCase();
}

function isConstructor(node) {
  return node.kind === "constructor";
}

function isModuleLevel(declaration) {
  const parent = declaration.parent;
  if (!parent) return false;
  if (parent.type === "Program") return true;
  return parent.type === "ExportNamedDeclaration" && parent.parent?.type === "Program";
}

function unwrapTypeAssertions(node) {
  let current = node;
  while (
    current &&
    (current.type === "TSAsExpression" ||
      current.type === "TSSatisfiesExpression" ||
      current.type === "TSNonNullExpression")
  ) {
    current = current.expression;
  }
  return current;
}

function isAsConst(node) {
  return (
    node?.type === "TSAsExpression" &&
    node.typeAnnotation?.type === "TSTypeReference" &&
    node.typeAnnotation.typeName?.type === "Identifier" &&
    node.typeAnnotation.typeName.name === "const"
  );
}

function isPrimitiveLiteral(node) {
  const value = unwrapTypeAssertions(node);
  if (!value) return false;
  if (value.type === "Literal") {
    // `raw` instead of a null comparison: this file must pass the repo's own no-null rules.
    return value.raw !== "null" && !value.regex;
  }
  if (value.type === "TemplateLiteral") return value.expressions.length === 0;
  if (value.type === "UnaryExpression" && value.operator === "-") {
    return value.argument?.type === "Literal" && typeof value.argument.value === "number";
  }
  return false;
}

function calleeName(callee) {
  if (!callee) return undefined;
  if (callee.type === "Identifier") return callee.name;
  if (callee.type === "MemberExpression" && !callee.computed) {
    const object = callee.object?.type === "Identifier" ? `${callee.object.name}.` : "*.";
    return object + keyName(callee.property);
  }
  return undefined;
}

// `null` stays legal where a platform API requires it.
const NULL_ARGUMENTS = [
  { callee: /^Object\.create$/, index: 0 },
  { callee: /^(?:React\.)?useRef$/, index: 0 },
  { callee: /^JSON\.stringify$/, index: 1 },
  { callee: /^(?:Object|Reflect)\.setPrototypeOf$/, index: 1 },
  { callee: /^\*\.insertBefore$/, index: 1 },
];

function isAllowedNullArgument(node) {
  const call = node.parent;
  if (call?.type !== "CallExpression" && call?.type !== "NewExpression") return false;
  const name = calleeName(call.callee);
  if (!name) return false;
  const index = call.arguments.indexOf(node);
  return NULL_ARGUMENTS.some(
    (entry) => entry.index === index && (entry.callee.test(name) || entry.callee.test(`*.${name.split(".").pop()}`)),
  );
}

const noNull = {
  meta: {
    type: "suggestion",
    docs: { description: "Use `undefined` for absent values; convert `null` at boundaries." },
    schema: [
      {
        type: "object",
        properties: { checkComparisons: { type: "boolean" } },
        additionalProperties: false,
      },
    ],
    messages: {
      literal: "Use `undefined` instead of `null`. At a boundary, convert with `value ?? undefined`.",
      type: "Use `undefined` instead of `null` in types (`T | undefined` or an optional property).",
    },
  },
  create(context) {
    const checkComparisons = context.options[0]?.checkComparisons ?? true;
    return {
      Literal(node) {
        if (node.raw !== "null") return;
        if (isAllowedNullArgument(node)) return;
        const parent = node.parent;
        if (
          !checkComparisons &&
          parent?.type === "BinaryExpression" &&
          ["==", "===", "!=", "!=="].includes(parent.operator)
        ) {
          return;
        }
        context.report({ node, messageId: "literal" });
      },
      TSNullKeyword(node) {
        context.report({ node, messageId: "type" });
      },
    };
  },
};

const noGetters = {
  meta: {
    type: "suggestion",
    docs: { description: "Expose state through explicit methods, not class getters." },
    schema: [],
    messages: {
      getter: "Replace getter `{{name}}` with an explicit method `{{method}}()`.",
    },
  },
  create(context) {
    function check(node) {
      if (node.kind !== "get" || node.computed) return;
      const name = keyName(node.key);
      if (!name) return;
      const plain = name.replace(/^#/, "");
      const method = /^(?:is|has|can|should)[A-Z]/.test(plain)
        ? plain
        : `get${plain.charAt(0).toUpperCase()}${plain.slice(1)}`;
      context.report({ node: node.key, messageId: "getter", data: { name, method } });
    }
    return { MethodDefinition: check, TSAbstractMethodDefinition: check };
  },
};

const readonlyProps = {
  meta: {
    type: "suggestion",
    docs: { description: "Mark properties `readonly` unless the class reassigns them." },
    schema: [],
    messages: {
      signature: "Mark property `{{name}}` as `readonly`.",
      field: "Mark field `{{name}}` as `readonly` (it is never reassigned outside the constructor).",
      parameter: "Mark parameter property `{{name}}` as `readonly`.",
    },
  },
  create(context) {
    const classes = [];
    let constructorDepth = 0;

    function markReassigned(target) {
      if (target?.type !== "MemberExpression" || target.computed) return;
      if (target.object?.type !== "ThisExpression") return;
      const current = classes[classes.length - 1];
      if (!current || constructorDepth > 0) return;
      const name = keyName(target.property);
      if (name) current.reassigned.add(name);
    }

    return {
      TSPropertySignature(node) {
        if (node.readonly) return;
        const name = keyName(node.key) ?? "[computed]";
        context.report({ node: node.key ?? node, messageId: "signature", data: { name } });
      },
      TSParameterProperty(node) {
        if (node.readonly) return;
        const parameter = node.parameter?.type === "AssignmentPattern" ? node.parameter.left : node.parameter;
        const name = parameter?.type === "Identifier" ? parameter.name : "parameter";
        context.report({ node, messageId: "parameter", data: { name } });
      },
      ClassBody(node) {
        classes.push({ node, reassigned: new Set() });
      },
      "ClassBody:exit"() {
        const current = classes.pop();
        if (!current) return;
        for (const member of current.node.body) {
          if (member.type !== "PropertyDefinition" && member.type !== "TSAbstractPropertyDefinition") continue;
          if (member.readonly || member.declare || member.computed) continue;
          const name = keyName(member.key);
          if (!name || current.reassigned.has(name)) continue;
          context.report({ node: member.key, messageId: "field", data: { name } });
        }
      },
      MethodDefinition(node) {
        if (isConstructor(node)) constructorDepth += 1;
      },
      "MethodDefinition:exit"(node) {
        if (isConstructor(node)) constructorDepth -= 1;
      },
      AssignmentExpression(node) {
        markReassigned(node.left);
      },
      UpdateExpression(node) {
        markReassigned(node.argument);
      },
    };
  },
};

const naming = {
  meta: {
    type: "suggestion",
    docs: {
      description:
        "PascalCase types/classes/enums, SCREAMING_SNAKE_CASE enum members, camelCase functions/methods/variables.",
    },
    schema: [],
    messages: {
      wrongCase: "{{kind}} `{{name}}` should be {{expected}}.",
    },
  },
  create(context) {
    const jsx = isJsxFile(context.filename ?? "");

    function check(node, name, kind, patterns, expected) {
      if (!name) return;
      const plain = bare(name.replace(/^#/, ""));
      if (plain === "") return;
      if (patterns.some((pattern) => pattern.test(plain))) return;
      context.report({ node, messageId: "wrongCase", data: { kind, name, expected } });
    }

    function checkBinding(node, kind) {
      if (!node) return;
      if (node.type === "Identifier") {
        check(node, node.name, kind, [CAMEL, UPPER, PASCAL], "camelCase (or SCREAMING_SNAKE_CASE / PascalCase)");
      } else if (node.type === "AssignmentPattern") {
        checkBinding(node.left, kind);
      } else if (node.type === "RestElement") {
        checkBinding(node.argument, kind);
      } else if (node.type === "ArrayPattern") {
        for (const element of node.elements) checkBinding(element, kind);
      } else if (node.type === "ObjectPattern") {
        for (const property of node.properties) {
          // `{ first_name }` mirrors an external shape; only renamed bindings are ours.
          if (property.type === "RestElement") checkBinding(property.argument, kind);
          else if (!property.shorthand) checkBinding(property.value, kind);
        }
      }
    }

    function checkParameter(parameter) {
      if (!parameter) return;
      if (parameter.type === "TSParameterProperty") {
        checkParameter(parameter.parameter);
        return;
      }
      if (parameter.type === "AssignmentPattern") {
        checkParameter(parameter.left);
        return;
      }
      if (parameter.type === "RestElement") {
        checkParameter(parameter.argument);
        return;
      }
      if (parameter.type === "Identifier") {
        const patterns = jsx ? [CAMEL, PASCAL] : [CAMEL];
        check(parameter, parameter.name, "Parameter", patterns, "camelCase");
      }
    }

    function checkFunctionParameters(node) {
      for (const parameter of node.params ?? []) checkParameter(parameter);
    }

    function checkMember(node, kind) {
      if (node.computed || node.kind === "constructor") return;
      const name = keyName(node.key);
      if (!name || node.key.type === "Literal") return;
      const patterns = node.static && node.readonly ? [CAMEL, UPPER] : [CAMEL];
      check(node.key, name, kind, patterns, "camelCase");
    }

    return {
      TSEnumDeclaration(node) {
        check(node.id, node.id?.name, "Enum", [PASCAL], "PascalCase");
      },
      TSEnumMember(node) {
        const name = node.id?.type === "Identifier" ? node.id.name : node.id?.value;
        if (typeof name === "string") check(node.id, name, "Enum member", [UPPER], "SCREAMING_SNAKE_CASE");
      },
      ClassDeclaration(node) {
        if (node.id) check(node.id, node.id.name, "Class", [PASCAL], "PascalCase");
      },
      ClassExpression(node) {
        if (node.id) check(node.id, node.id.name, "Class", [PASCAL], "PascalCase");
      },
      TSInterfaceDeclaration(node) {
        check(node.id, node.id?.name, "Interface", [PASCAL], "PascalCase");
      },
      TSTypeAliasDeclaration(node) {
        check(node.id, node.id?.name, "Type", [PASCAL], "PascalCase");
      },
      TSTypeParameter(node) {
        const name = typeof node.name === "string" ? node.name : node.name?.name;
        check(node, name, "Type parameter", [PASCAL], "PascalCase");
      },
      FunctionDeclaration(node) {
        if (node.id && !HTTP_METHOD_HANDLERS.has(node.id.name)) {
          const patterns = jsx || isDecoratorFactory(node) ? [CAMEL, PASCAL] : [CAMEL];
          check(node.id, node.id.name, "Function", patterns, jsx ? "camelCase (PascalCase for components)" : "camelCase");
        }
        checkFunctionParameters(node);
      },
      FunctionExpression: checkFunctionParameters,
      ArrowFunctionExpression: checkFunctionParameters,
      MethodDefinition(node) {
        checkMember(node, "Method");
      },
      TSAbstractMethodDefinition(node) {
        checkMember(node, "Method");
      },
      PropertyDefinition(node) {
        checkMember(node, "Property");
      },
      VariableDeclarator(node) {
        checkBinding(node.id, "Variable");
      },
      CatchClause(node) {
        if (node.param) checkBinding(node.param, "Catch parameter");
      },
    };
  },
};

const constantCase = {
  meta: {
    type: "suggestion",
    docs: { description: "Module-level primitive constants use SCREAMING_SNAKE_CASE." },
    schema: [
      {
        type: "object",
        properties: { allow: { type: "array", items: { type: "string" } } },
        additionalProperties: false,
      },
    ],
    messages: {
      constant: "Module-level constant `{{name}}` should be SCREAMING_SNAKE_CASE (`{{suggestion}}`).",
    },
  },
  create(context) {
    const allow = new Set([...FRAMEWORK_CONSTANTS, ...(context.options[0]?.allow ?? [])]);
    return {
      VariableDeclaration(node) {
        if (node.kind !== "const" || !isModuleLevel(node)) return;
        for (const declarator of node.declarations) {
          if (declarator.id?.type !== "Identifier" || !isPrimitiveLiteral(declarator.init)) continue;
          const name = declarator.id.name;
          if (allow.has(name) || UPPER.test(bare(name))) continue;
          context.report({
            node: declarator.id,
            messageId: "constant",
            data: { name, suggestion: toUpperSnake(name) },
          });
        }
      },
    };
  },
};

const preferAsConstConstants = {
  meta: {
    type: "suggestion",
    docs: { description: "SCREAMING_SNAKE_CASE array/object constants end with `as const`." },
    schema: [],
    messages: {
      asConst: "Constant `{{name}}` should end with `as const` so it stays read-only and literal-typed.",
    },
  },
  create(context) {
    return {
      VariableDeclaration(node) {
        if (node.kind !== "const" || !isModuleLevel(node)) return;
        for (const declarator of node.declarations) {
          if (declarator.id?.type !== "Identifier" || declarator.id.typeAnnotation) continue;
          if (!UPPER.test(bare(declarator.id.name))) continue;
          let init = declarator.init;
          if (init?.type === "TSSatisfiesExpression") init = init.expression;
          if (isAsConst(init)) continue;
          if (init?.type !== "ArrayExpression" && init?.type !== "ObjectExpression") continue;
          context.report({ node: declarator.id, messageId: "asConst", data: { name: declarator.id.name } });
        }
      },
    };
  },
};

const filenameCase = {
  meta: {
    type: "suggestion",
    docs: { description: "Filenames are kebab-case; dot-separated role suffixes are kebab-case too." },
    schema: [
      {
        type: "object",
        properties: { ignore: { type: "array", items: { type: "string" } } },
        additionalProperties: false,
      },
    ],
    messages: {
      filename: "Filename `{{name}}` should be kebab-case (`{{suggestion}}`).",
    },
  },
  create(context) {
    const ignore = (context.options[0]?.ignore ?? []).map((pattern) => new RegExp(pattern));
    return {
      Program(node) {
        const name = basename(context.filename ?? "");
        const match = SOURCE_EXTENSION.exec(name);
        if (!match || ignore.some((pattern) => pattern.test(name))) return;
        const [, stem, extension] = match;
        // Dots inside `[...slug]` route segments are not separators.
        const segments = stem.match(/\[\[?[^\]]*\]\]?|[^.]+/g) ?? [stem];
        if (segments.every((segment) => KEBAB_SEGMENT.test(segment))) return;
        const suggestion = segments.map((segment) => (KEBAB_SEGMENT.test(segment) ? segment : toKebab(segment))).join(".") + extension;
        context.report({ node, messageId: "filename", data: { name, suggestion } });
      },
    };
  },
};

const noGenericError = {
  meta: {
    type: "suggestion",
    docs: { description: "Throw typed exceptions, not a bare `Error`." },
    schema: [],
    messages: {
      generic: "Throw a typed exception (e.g. `ArgumentInvalidException`) instead of a generic `Error`.",
    },
  },
  create(context) {
    return {
      ThrowStatement(node) {
        const argument = node.argument;
        if (argument?.type !== "NewExpression" && argument?.type !== "CallExpression") return;
        if (argument.callee?.type === "Identifier" && argument.callee.name === "Error") {
          context.report({ node: argument, messageId: "generic" });
        }
      },
    };
  },
};

function parentDepth(source) {
  let depth = 0;
  for (const part of source.split("/")) {
    if (part === "..") depth += 1;
    else if (part !== ".") break;
  }
  return depth;
}

const noDeepRelativeImports = {
  meta: {
    type: "suggestion",
    docs: { description: "Cross-module imports use the path alias, not `../../` chains." },
    schema: [
      {
        type: "object",
        properties: {
          maxParentDepth: { type: "integer", minimum: 0 },
          alias: { type: "string" },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      deep: "Import `{{source}}` climbs {{depth}} directories; use the `{{alias}}` alias for cross-module imports.",
    },
  },
  create(context) {
    const maxParentDepth = context.options[0]?.maxParentDepth ?? 1;
    const alias = context.options[0]?.alias ?? "@/";

    function check(sourceNode) {
      if (sourceNode?.type !== "Literal" || typeof sourceNode.value !== "string") return;
      const depth = parentDepth(sourceNode.value);
      if (depth <= maxParentDepth) return;
      context.report({
        node: sourceNode,
        messageId: "deep",
        data: { source: sourceNode.value, depth: String(depth), alias },
      });
    }

    return {
      ImportDeclaration: (node) => check(node.source),
      ExportNamedDeclaration: (node) => check(node.source),
      ExportAllDeclaration: (node) => check(node.source),
      ImportExpression: (node) => check(node.source),
      CallExpression(node) {
        if (node.callee?.type === "Identifier" && node.callee.name === "require") check(node.arguments[0]);
      },
    };
  },
};

export default {
  meta: { name: "js-ts-conventions", version: "1.0.0" },
  rules: {
    "no-null": noNull,
    "no-getters": noGetters,
    "readonly-props": readonlyProps,
    naming,
    "constant-case": constantCase,
    "prefer-as-const-constants": preferAsConstConstants,
    "filename-case": filenameCase,
    "no-generic-error": noGenericError,
    "no-deep-relative-imports": noDeepRelativeImports,
  },
};
